package com.jackandpaws.service; import com.jackandpaws.exception.ApiException;import com.jackandpaws.model.User;import com.jackandpaws.repository.UserRepository;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.stereotype.Service;
@Service public class CurrentUserService {private final UserRepository users;public CurrentUserService(UserRepository u){users=u;}public User get(){var auth=SecurityContextHolder.getContext().getAuthentication();if(auth==null||!auth.isAuthenticated())throw new ApiException(401,"Authentication required");return users.findById(Long.valueOf(auth.getName())).orElseThrow(()->new ApiException(401,"User account not found"));}}
